import { materializeAws } from "./aws.js";
import { materializeAzure } from "./azure.js";
import { materializeGcp } from "./gcp.js";
import { materializeOci } from "./oci.js";

const BUNDLES = {
  aws: materializeAws,
  azure: materializeAzure,
  gcp: materializeGcp,
  oci: materializeOci,
};

export function materializeBundles(lab, workspace, lock) {
  const files = {};
  const env = {
    TF_CLI_CONFIG_FILE: "/opt/drydock/terraform.rc",
    TF_IN_AUTOMATION: "1",
    TF_INPUT: "0",
    CHECKPOINT_DISABLE: "1",
  };
  const prepare = [];
  for (const cloud of lab.clouds) {
    const build = BUNDLES[cloud];
    if (!build) throw new Error(`No provider bundle for ${cloud}`);
    const part = build({ lab, workspace, lock });
    if (part.files["provider.tf"] && files["provider.tf"]) {
      files["provider.tf"] += `\n${part.files["provider.tf"].replace(/^# Generated by Drydock.*\n/, "")}`;
      for (const [name, contents] of Object.entries(part.files)) {
        if (name !== "provider.tf") files[name] = contents;
      }
    } else {
      Object.assign(files, part.files);
    }
    Object.assign(env, part.env);
    prepare.push(...(part.prepare ?? []));
  }
  return { files, env, prepare };
}
